// ───────── รางวัล ─────────
function give(spec){const out=[];if(!spec)return'';const W=(()=>{try{return W15()}catch(e){return 1}})()||1;
 spec.split(',').forEach(p=>{const [k,v0]=p.split(':');const pct=/%$/.test(v0||''),v=parseFloat(v0)||0;
  const add=(f,base,lab)=>{const cur=S[f]||0;const d=Math.round(pct?Math.max(base,cur*v/100):v);S[f]=cur+d;out.push(`${lab} ${d>=0?'+':''}${typeof fmt==='function'?fmt(d):d}`)};
  switch(k){case'pow':add('power',5,'พลัง');break;case'qi':add('qi',3,'ลมปราณ');break;case'int':add('int',2,'ปัญญา');break;case'cha':add('cha',2,'เสน่ห์');break;
   case'fame':add('fame',3,'ชื่อเสียง');break;case'karma':add('karma',2,'กรรม');break;
   case'money':{const d=Math.round(pct?Math.max(20*W,(S.money||0)*v/100):v*W);S.money=Math.max(0,(S.money||0)+d);out.push(`เงิน ${d>=0?'+':''}${typeof fmt==='function'?fmt(d):d}`);break}
   case'joy':try{joy(v)}catch(e){S.happy=Math.max(0,Math.min(100,(S.happy||60)+v))}out.push(`ความสุข ${v>=0?'+':''}${v}`);break;
   case'hp':{const mh=S.maxHp||100;S.hp=v>=100?mh:Math.min(mh,Math.max(1,(S.hp||mh)+Math.round(mh*v/100)));out.push(v>=100?'พลังชีวิตเต็ม':`พลังชีวิต ${v>0?'+':''}${v}%`);break}
   case'mhp':{const d=Math.round(pct?Math.max(5,(S.maxHp||100)*v/100):v);S.maxHp=(S.maxHp||100)+d;out.push(`พลังชีวิตสูงสุด +${d}`);break}
   case'life':S.lifespan=(S.lifespan||60)+v;out.push(`อายุขัย +${v} ปี`);break}});
 return out.join(' · ')}

