const WG={all:'ทุกโลก',murim:'ยุทธภพ',xian:'โลกเซียน',mw:'ยุคปัจจุบัน',soul:'จิตวิญญาณยุทธ์',loop:'ผู้ย้อนกาล',beast:'เกิดเป็นสัตว์',sky:'ทะลุฟ้าดารา',fog:'นครม่านหมอก',hell:'โหมดนรก',short:'โหมดชีวิตสั้น',junk:'โหมดรากขยะ'};
const MODEW={hell:1,short:1,junk:1};
const okW=(e,s)=>e[1]==='all'||(MODEW[e[1]]?s.mode===e[1]:s.w===e[1]);

// ───────── ค้นพบ ─────────
function discover(e,why){const F=found();const first=!F[e[0]];if(first){F[e[0]]={t:Date.now(),n:String(S.name||''),a:S.age|0};LSS('murim_secrets',F)}
 const n=Object.keys(F).length;
 try{if(typeof island==='function')island({big:1,pri:1,now:1,key:'scr'+e[0],ic:'🔮',h:first?`ค้นพบความลับ ${n}/${T.length}`:'ความลับที่เคยพบ',t:e[3],d:first?'เพราะชีวิตนี้คุณ… '+e[4]:'',kind:'good',ms:6500})}catch(x){}
 if(first){try{document.body.classList.add('scrFx');setTimeout(()=>document.body.classList.remove('scrFx'),1600)}catch(x){}}}
const got=id=>!!SC().got[id];const mark=id=>{SC().got[id]=1};

// ───────── ตัวนับการเลือก ─────────
const R_NO=/ปฏิเสธ|ไม่รับ|ไม่ไป|ถอย|ปล่อยผ่าน|เมิน|ไม่ยุ่ง|เดินผ่าน|ไม่สน/,R_KIND=/ช่วย|แบ่ง|ดูแล|รับเลี้ยง|ปกป้อง|รักษา|ไว้ชีวิต|บริจาค|ให้อภัย/,R_RUTH=/ฆ่า|สังหาร|ปลิดชีพ|ทรมาน|บุก|ทำลาย/,R_FORG=/อภัย|ยกโทษ|ปล่อยเขา|ไม่ถือสา|คืนดี/,R_FIGHT=/สู้|ดวล|ท้า|ประลอง|บุก/,R_FLEE=/หนี|ถอย|หลบ/,R_GIFT=/ให้|บริจาค|แบ่ง|แจก/,R_LIE=/หลอก|โกหก|ลวง/;
function onPick(t){const s=SC(),x=strip(t);s.ch++;if(R_NO.test(x)){s.no++;s.noMax=Math.max(s.noMax,s.no)}else{s.no=0;s.yes++}
 if(R_KIND.test(x)){s.kind++;if((S.pers&&S.pers.ruth||0)>=6&&S.age>=40)s.kindAfter++}if(R_RUTH.test(x)){s.ruth++;if(S.age>=40)s.ruth40++}
 if(R_FORG.test(x))s.forgive++;if(R_FIGHT.test(x))s.fight++;if(R_FLEE.test(x))s.flee++;if(R_GIFT.test(x))s.gift++;if(R_LIE.test(x))s.lie++}
function onYear(){const s=SC();try{const f=S.focus||'';if(f)s.fy[f]=(s.fy[f]||0)+1}catch(e){}
 const c=ctx();if(c.mon<50)s.poor++;if(c.mon>=50000)s.rich++;if(c.j<30)s.sad++;if(c.j>80)s.glad++;if(c.hpR<.2)s.low++;if((S.kills|0)===s.k0)s.noKill++;s.k0=S.kills|0;
 if(c.a===1&&S.name)LSS('murim_lastName',LSG('murim_curName',''));if(S.name)LSS('murim_curName',S.name)}

// ───────── ฉากลับประจำปี ─────────
let busy=0;
function yearly(){if(!alive())return;const s=ctx();if(s.a<1)return;
 const cand=T.filter(e=>(e[2]==='y'||e[2]==='s')&&okW(e,s)&&!got(e[0])&&(()=>{try{return e[5](s)}catch(x){return false}})());
 if(!cand.length)return;const exact=e=>/s\.a===|=== *s\.a/.test(String(e[5]));
 const ex=cand.filter(exact),pickL=ex.length?ex.slice(0,2):[cand[Math.floor(Math.random()*cand.length)]];
 pickL.forEach((e,k)=>setTimeout(()=>fire(e),k*900));}
function fire(e){if(!alive()||got(e[0]))return;if(e[2]==='y'&&!/s\.a===|=== *s\.a/.test(String(e[5]))&&Math.random()>.7)return;
 mark(e[0]);
 if(e[2]==='s'&&!autoOn()){sceneQ.push(e);setTimeout(scene,800);return}
 const o=e[2]==='s'?e[8].o[0]:null;
 busy=1;try{const rw=give(o?o[2]:e[7]);log(`🔮 <b>${E(e[3])}</b> · ${E(o?e[6]+' — '+o[1]:e[6])}${rw?` <span class="tag2">(${E(rw)})</span>`:''}`,'epic');discover(e)}catch(x){}busy=0}
let sceneQ=[],scTry=0;
function scene(){if(!sceneQ.length||!alive())return;let blocked=false;try{blocked=modalOpen||!!choice._cur||!!(window._CO&&window._CO.id)}catch(x){}
 if(blocked){if(++scTry<30)return setTimeout(scene,1500);scTry=0;const L=sceneQ.splice(0);busy=1;L.forEach(e=>{try{const o=e[8].o[0],rw=give(o[2]);log(`🔮 <b>${E(e[3])}</b> · ${E(e[6]+' — '+o[1])}${rw?` <span class="tag2">(${E(rw)})</span>`:''}`,'epic');discover(e)}catch(x){}});busy=0;return}scTry=0;
 const e=sceneQ.shift();let was=null;try{was=paused;paused=true}catch(x){}
 modal(`<div class="scrS"><small>🔮 ฉากลับ · อายุ ${S.age|0}</small><h3>${E(e[3])}</h3><p>${E(e[6])}</p><div class="scrO">${e[8].o.map((o,i)=>`<button class="opt" data-i="${i}">${E(o[0])}</button>`).join('')}</div></div>`,'scrscene');
 const m=$$('modal');m.querySelectorAll('.scrO button').forEach(b=>b.onclick=()=>{const o=e[8].o[+b.dataset.i];busy=1;try{const rw=give(o[2]);closeM();log(`🔮 <b>${E(e[3])}</b> · ${E(o[0])} — ${E(o[1])}${rw?` <span class="tag2">(${E(rw)})</span>`:''}`,'epic');discover(e);try{onPick(o[0])}catch(x){}}catch(x){}busy=0;try{paused=was}catch(x){}try{render()}catch(x){}})}

// ───────── ตัวเลือกลับ ─────────
function wrapChoice(){const o=window.choice;if(typeof o!=='function'||o._scr)return;
 const w=function(title,text,opts){try{if(alive()&&Array.isArray(opts)&&opts.length&&opts.length<7&&!opts._scr&&!opts.some(x=>x&&x._scr)&&!autoOn()){opts._scr=1;const s=ctx(),cx=strip(title)+' '+strip(text);
   const cand=T.filter(e=>e[2]==='c'&&okW(e,s)&&!got(e[0])&&e[8].re.test(cx)&&(()=>{try{return e[5](s)}catch(x){return false}})());
   if(cand.length){const e=cand[Math.floor(Math.random()*cand.length)];const base=opts.find(x=>x&&typeof x.f==='function'&&!/เสี่ยง|บุก|ฆ่า|สังหาร/.test(strip(x.t)+' '+strip(x.s||'')))||opts.find(x=>x&&typeof x.f==='function');
    if(base){const bf=base.f;const keep=opts._lf;opts=opts.concat([{t:e[8].lab,s:'🔮 ทางลับ · เปิดได้เพราะชีวิตที่ผ่านมาของคุณ',_scr:e[0],f(){mark(e[0]);let r;busy=1;try{const rw=give(e[7]);log(`🔮 <b>${E(e[3])}</b> · ${E(e[6])}${rw?` <span class="tag2">(${E(rw)})</span>`:''}`,'epic');discover(e)}catch(x){}busy=0;try{r=bf.apply(base,arguments)}catch(x){}return r}}]);opts._scr=1;if(keep)opts._lf=keep}}}}catch(x){console.error('scrChoice',x)}
  return o.call(this,title,text,opts)};
 Object.assign(w,o);w._scr=1;window.choice=w;try{choice=w}catch(x){}}
function decorate(){try{const c=choice._cur,m=$$('modal');if(!c||!m||m.dataset.k!=='choice')return;c.opts.forEach((o,i)=>{if(o&&o._scr){const b=m.querySelector(`.opt[data-i="${i}"]`);if(b)b.classList.add('scrOpt')}})}catch(x){}}

// ───────── ตอนจบลับ ─────────
function ending(){try{const E0=$$('end');if(!E0||E0.querySelector('.scrEnd'))return;const s=ctx();
 const L=T.filter(e=>e[2]==='e'&&okW(e,s)&&(()=>{try{return e[5](s)}catch(x){return false}})()).slice(0,3);if(!L.length)return;
 L.forEach(e=>discover(e));
 const d=document.createElement('div');d.className='scrEnd';d.innerHTML=`<b>🔮 ตอนจบลับ</b>${L.map(e=>`<div><b>${E(e[3])}</b><br>${E(e[6])}</div>`).join('')}`;
 const h=E0.querySelector('.lfEnd')||E0.querySelector('h2,h3,.big');(h||E0.firstElementChild||E0).insertAdjacentElement(h?'afterend':'afterbegin',d)}catch(x){console.error('scrEnd',x)}}

// ───────── สมุดความลับ ─────────
window._secretBook=function(tab){const F=found();const groups=Object.keys(WG);tab=tab||'all';
 const L=T.filter(e=>e[1]===tab);const n=Object.keys(F).length;
 const TY={c:'ตัวเลือกลับ',y:'ฉากลับ',s:'ฉากลับ',e:'ตอนจบลับ'};
 modal(`<button class="xbtn" onclick="closeM()">✕</button><h3>🔮 สมุดความลับ</h3><p class="tag2">ค้นพบแล้ว <b>${n}</b> / ${T.length} · คำใบ้เป็นกลอนสั้นๆ ลองเล่นให้ชีวิตเดินไปตามนั้น</p>
 ${LSG('murim_bday',null)?'':`<div class="scrBd">🎂 ใส่วันเกิดจริงของคุณ (ไม่บังคับ · เก็บไว้ในเครื่องนี้เท่านั้น) จะปลดความลับ “ลูกรักของฟ้า” ได้ <input type="date" id="scrBdI"><button onclick="(function(){var v=document.getElementById('scrBdI').value;if(!v)return;var d=new Date(v);LS.set('murim_bday',{m:d.getMonth()+1,d:d.getDate()});_secretBook('${'${tab}'}')})()">บันทึก</button></div>`}
 <div class="scrBar"><i style="width:${Math.round(n/T.length*100)}%"></i></div>
 <div class="scrTabs">${groups.map(g=>{const all=T.filter(e=>e[1]===g),f=all.filter(e=>F[e[0]]).length;return `<button class="${g===tab?'on':''}" onclick="_secretBook('${g}')">${WG[g]} <small>${f}/${all.length}</small></button>`}).join('')}</div>
 <div class="scrList">${L.map(e=>{const f=F[e[0]];return f?`<div class="scrI ok"><div class="scrT"><b>${E(e[3])}</b><span>${TY[e[2]]}</span></div><small>เพราะชีวิตนี้คุณ… ${E(e[4])}</small><small class="scrW">พบครั้งแรกโดย ${E(f.n||'ไม่ทราบชื่อ')} · อายุ ${f.a}</small></div>`:`<div class="scrI"><div class="scrT"><b>???</b><span>${TY[e[2]]}</span></div><small>“${E(e[4])}”</small></div>`}).join('')}</div>`,'secrets')};
window.secretBook=()=>window._secretBook();

// ───────── เสียบเข้ากับเกม ─────────
const after=(name,fn)=>{try{const o=window[name];if(typeof o!=='function'||o['_scr_'+name])return;const w=function(){const r=o.apply(this,arguments);try{fn.apply(this,arguments)}catch(e){}return r};try{Object.assign(w,o)}catch(e){}w['_scr_'+name]=1;window[name]=w}catch(e){}};
const before=(name,fn)=>{try{const o=window[name];if(typeof o!=='function'||o['_scrb_'+name])return;const w=function(){try{fn.apply(this,arguments)}catch(e){}return o.apply(this,arguments)};try{Object.assign(w,o)}catch(e){}w['_scrb_'+name]=1;window[name]=w}catch(e){}};
before('choiceRun',i=>{try{const c=choice._cur;if(c&&c.opts[i])onPick(c.opts[i].t)}catch(e){}});
after('passYear',()=>{if(!alive())return;onYear();yearly()});
after('choiceShow',decorate);
after('endGame',()=>{setTimeout(ending,500);setTimeout(ending,1500)});
